use crate::aap::caps::{http_client, inference_llm};

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

const MODERATE_SYSTEM: &str = "You are a content moderator for customer support messages. \
Reply with exactly one word: ALLOW if the message is acceptable, VIOLATION if it breaks \
content policy, or ESCALATE if a human must review it.";

fn hex_digit(n: u8) -> char {
    b"0123456789ABCDEF"[n as usize] as char
}

fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len() * 3);
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(hex_digit(b >> 4));
                out.push(hex_digit(b & 0x0F));
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(query: CustomerQuery) -> ModerationResult {
        // Enrichment fetch: performed on every call, but its result is
        // deliberately discarded so the node's output does not depend on it.
        // A transport failure is a value and is ignored; an out-of-allowlist
        // request traps at the boundary as specified.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&query.question));
        let _ = http_client::fetch(&url);

        let reply = inference_llm::infer(MODERATE_SYSTEM, &query.question, "moderate");
        let verdict = reply.trim().to_ascii_uppercase();

        if verdict.starts_with("ALLOW") {
            ModerationResult::Ok(ModeratedQuery { query })
        } else if verdict.starts_with("VIOLATION") {
            ModerationResult::Violation(PolicyViolation {
                reason: "content policy violation".to_string(),
            })
        } else {
            // Fail closed: anything other than an explicit ALLOW or VIOLATION
            // is routed to a human.
            ModerationResult::Escalation(EscalationRequest {
                query,
                reason: "moderation verdict requires human review".to_string(),
            })
        }
    }
}

export!(Node);
```

